mapper.select:
SELECT 
  FROM emp08_license
  JOIN emp01_person ON emp08_person_id = emp01_person_id
 WHERE emp01_company_id = #{companyId}
   AND emp08_person_id  = #{personId}
 ORDER BY emp08_certified_dt DESC

mapper.update:
UPDATE emp08_license
   SET emp08_certified_dt     = #{req.certifiedDt}
     , emp08_certified_nm     = #{req.certifiedNm}
     , emp08_license_no       = #{req.licenseNo}
     , emp08_issuing_agency   = #{req.issuingAgency}
     , emp08_issuing_grade    = #{req.issuingGrade}
     , emp08_finance_relate_yn = #{req.financeRelateYn}
     , emp08_kofia_reg_date   = #{req.kofiaRegDate}
     , emp08_note             = #{req.note}
 WHERE emp08_license_id = #{licenseId}
   AND emp08_person_id IN (
       SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId}
   )

mapper.delete:
